```python
def map_obj_to_commands(updates, module, warnings):
    commands = list()
    want, have = updates

    def needs_update(x):
        return want.get(x) is not None and (want.get(x) != have.get(x))

    def add(cmd):
        if 'management api http-commands' not in commands:
            commands.insert(0, 'management api http-commands')
        commands.append(cmd)

    # Protocol commands
    protocols = ['http', 'https', 'local_http']
    ports = {
        'http': 80,
        'https': 443,
        'local_http': 8080
    }

    for protocol in protocols:
        if needs_update(protocol) or needs_update(f'{protocol}_port'):
            if want[protocol] is False:
                add(f'no protocol {protocol}')
            else:
                if have[protocol] is False and want[protocol] in (False, None):
                    warnings.append(f'protocol {protocol} is not enabled, not configuring {protocol}_port value')
                else:
                    port = want.get(f'{protocol}_port') or ports[protocol]
                    add(f'protocol {protocol} port {port}')

    # Handle socket
    if needs_update('socket'):
        if want['socket'] is False:
            add('no protocol unix-socket')
        else:
            add('protocol unix-socket')

    # Handle state
    if needs_update('state'):
        if want['state'] == 'stopped':
            add('shutdown')
        elif want['state'] == 'started':
            add('no shutdown')

    # Handle VRF
    if needs_update('vrf'):
        add('vrf %s' % want['vrf'])
        if want['state'] == 'stopped':
            add('shutdown')
        elif want['state'] == 'started':
            add('no shutdown')

    return commands
